CREATE TABLE player (id BIGSERIAL PRIMARY KEY,riot_puuid VARCHAR(100) NOT NULL UNIQUE,game_name VARCHAR(32) NOT NULL,tag_line VARCHAR(16) NOT NULL,display_name VARCHAR(64) NOT NULL,portrait VARCHAR(255),competitive_tier VARCHAR(32) NOT NULL DEFAULT 'UNRANKED',rank_rating INTEGER,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',last_successful_synchronization_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE season (id BIGSERIAL PRIMARY KEY,external_id VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,active BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE valorant_match (id BIGSERIAL PRIMARY KEY,external_match_id VARCHAR(100) NOT NULL UNIQUE,season_id BIGINT NOT NULL REFERENCES season(id),started_at TIMESTAMPTZ NOT NULL,duration_seconds INTEGER,map_id VARCHAR(64),map_name VARCHAR(100) NOT NULL,game_mode VARCHAR(32) NOT NULL,red_score INTEGER,blue_score INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE player_match (id BIGSERIAL PRIMARY KEY,player_id BIGINT NOT NULL REFERENCES player(id),match_id BIGINT NOT NULL REFERENCES valorant_match(id),agent_id VARCHAR(64),agent_name VARCHAR(64) NOT NULL,result VARCHAR(16) NOT NULL,kills INTEGER NOT NULL,deaths INTEGER NOT NULL,assists INTEGER NOT NULL,score INTEGER NOT NULL,headshots INTEGER NOT NULL,bodyshots INTEGER NOT NULL,legshots INTEGER NOT NULL,damage_dealt INTEGER NOT NULL,rounds_played INTEGER NOT NULL,acs NUMERIC(8,2),adr NUMERIC(8,2),competitive_tier VARCHAR(32),rank_rating INTEGER,was_mvp BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_player_match_player_match UNIQUE(player_id,match_id));
CREATE TABLE challenge (id BIGSERIAL PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,description VARCHAR(500) NOT NULL,difficulty VARCHAR(20) NOT NULL,points INTEGER NOT NULL,category VARCHAR(30) NOT NULL,rule_type VARCHAR(20) NOT NULL,progress_mode VARCHAR(30) NOT NULL,conditions_json JSONB NOT NULL,exclusion_group VARCHAR(80),enabled BOOLEAN NOT NULL DEFAULT true,schema_version INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE weekly_challenge (id BIGSERIAL PRIMARY KEY,week_start DATE NOT NULL,challenge_id BIGINT NOT NULL REFERENCES challenge(id),selected_at TIMESTAMPTZ NOT NULL,finalized_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_weekly_challenge_week_challenge UNIQUE(week_start,challenge_id));
CREATE TABLE player_challenge_progress (id BIGSERIAL PRIMARY KEY,player_id BIGINT NOT NULL REFERENCES player(id),weekly_challenge_id BIGINT NOT NULL REFERENCES weekly_challenge(id),current_value NUMERIC(14,4) NOT NULL DEFAULT 0,target_value NUMERIC(14,4) NOT NULL,completed BOOLEAN NOT NULL DEFAULT false,completed_at TIMESTAMPTZ,calculated_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_progress_player_weekly_challenge UNIQUE(player_id,weekly_challenge_id));
CREATE TABLE weekly_player_score (id BIGSERIAL PRIMARY KEY,player_id BIGINT NOT NULL REFERENCES player(id),week_start DATE NOT NULL,points INTEGER NOT NULL DEFAULT 0,completed_challenges INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL,previous_position INTEGER,calculated_at TIMESTAMPTZ NOT NULL,finalized_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_weekly_score_player_week UNIQUE(player_id,week_start));
CREATE TABLE synchronization (id BIGSERIAL PRIMARY KEY,type VARCHAR(40) NOT NULL,trigger_type VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ,players_processed INTEGER NOT NULL DEFAULT 0,failure_count INTEGER NOT NULL DEFAULT 0,matches_imported INTEGER NOT NULL DEFAULT 0,error_message VARCHAR(2000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE synchronization_player_result (id BIGSERIAL PRIMARY KEY,synchronization_id BIGINT NOT NULL REFERENCES synchronization(id),player_id BIGINT NOT NULL REFERENCES player(id),status VARCHAR(20) NOT NULL,pages_fetched INTEGER NOT NULL DEFAULT 0,matches_imported INTEGER NOT NULL DEFAULT 0,error_message VARCHAR(2000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_sync_player_result UNIQUE(synchronization_id,player_id));
CREATE TABLE deep_synchronization_task (id BIGSERIAL PRIMARY KEY,player_id BIGINT NOT NULL REFERENCES player(id),season_id BIGINT NOT NULL REFERENCES season(id),status VARCHAR(20) NOT NULL,next_page INTEGER,next_cursor VARCHAR(500),last_match_started_at TIMESTAMPTZ,last_attempt_at TIMESTAMPTZ,finished_at TIMESTAMPTZ,error_message VARCHAR(2000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_match_started_at ON valorant_match(started_at DESC); CREATE INDEX idx_player_match_player ON player_match(player_id); CREATE INDEX idx_weekly_challenge_week ON weekly_challenge(week_start); CREATE INDEX idx_progress_weekly_challenge ON player_challenge_progress(weekly_challenge_id); CREATE INDEX idx_weekly_score_week_position ON weekly_player_score(week_start,position); CREATE INDEX idx_sync_created_at ON synchronization(created_at DESC);
CREATE UNIQUE INDEX uk_deep_sync_active ON deep_synchronization_task(player_id,season_id) WHERE status IN ('PENDING','RUNNING','PARTIAL');
